/*
 * A045360  Primes congruent to {1, 2, 4, 5, 6} mod 7.
 * https://oeis.org/A045360
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 43, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   grow_seq, is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Primes congruent to 1,2,4,5,6 mod 7 (OEIS A045360). */
/* Generated by iterative primality tests, cached for reuse. */

#include <stddef.h>            /* size_t */
#include "../utils/is_prime.h" /* is_prime(idx_t) */
#include "../utils/grow_seq.h" /* grow_seq(seq_t **, size_t *, size_t) */

seq_t a(idx_t n)
{
    /* Cache of previously computed terms. */
    static seq_t *cache      = NULL;
    static idx_t cached_cnt  = 0;   /* number of terms stored */
    static size_t cached_cap = 0;   /* current capacity of cache array */
    static idx_t next_candidate = 2;/* next integer to test for primality */

    if (n == 0) return (seq_t)0;   /* Undefined for index 0 – return 0. */

    /* Fill the cache until it contains at least n terms. */
    while (cached_cnt < n)
    {
        idx_t cand = next_candidate;
        /* Advance candidate for the next iteration. */
        next_candidate++;

        /* Only check primes for 2 and odd numbers (even >2 cannot be prime). */
        if ((cand == 2) || (cand > 2 && (cand & 1ULL)))
        {
            if (is_prime(cand))
            {
                idx_t mod7 = cand % 7ULL;
                /* Keep residues 1,2,4,5,6; skip 0 and 3. */
                if (mod7 != 0ULL && mod7 != 3ULL)
                {
                    /* Increase cache capacity if necessary. */
                    grow_seq(&cache, &cached_cap, (size_t)(cached_cnt + 1));
                    /* Store the found prime. */
                    cache[cached_cnt++] = (seq_t)cand;
                }
            }
        }
    }
    return cache[(size_t)(n - 1)];
}
